ValidationRule.errorConditionFormula:
AND(
OR(
ISPICKVAL(PRIORVALUE(StageName), '1 - Qualification'),ISPICKVAL(PRIORVALUE(StageName), '2 - Solution Developed'),ISPICKVAL(PRIORVALUE(StageName), '3 - Solution Agreed'),ISPICKVAL(PRIORVALUE(StageName), '4 - Negotiate')
),
OR(
ISPICKVAL(StageName, '6 - Setup'),ISPICKVAL(StageName, '7 - Closed')
),
NOT($Permission.VR_Bypass_Permission)
)
